1	/**
2	 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
5	 */
6	import {
7	  getLimit,
8	  getPlanLimits,
9	  wouldExceedLimit,
10	} from "@/config/plan-limits";
11	import { emit } from "@/lib/event-bus";
12	import { assertCan } from "@/lib/permissions";
13	import { assertOrgScope } from "@/lib/tenant";
14	import * as attachmentRepo from "@/server/repositories/attachment-repository";
15	import * as invoiceRepo from "@/server/repositories/invoice-repository";
16	import * as orgRepo from "@/server/repositories/organization-repository";
17	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
18	import * as usageRepo from "@/server/repositories/usage-repository";
19	import * as webhookRepo from "@/server/repositories/webhook-repository";
20	import { toIsoTimestamp } from "@/types/common";
21	import { actorEnvelope, billingResource, requireFound } from "./_support";
22	import type {
23	  CancelSubscriptionInput,
24	  ChangePlanInput,
25	  UpdateSeatsInput,
26	} from "@/schemas/billing";
27	import type {
28	  BillingSummary,
29	  Invoice,
30	  LimitCheck,
31	  LimitedResource,
32	  PlanId,
33	  Subscription,
34	} from "@/types/billing";
35	import type { OrgId } from "@/types/common";
36	import type { Actor } from "@/types/member";
37	
38	/** The dimensions the billing page shows a meter for. */
39	const SUMMARY_RESOURCES: readonly LimitedResource[] = [
40	  "seats",
41	  "projects",
42	  "storageMb",
43	  "webhooks",
44	];
45	
46	export async function getBillingSummary(
47	  actor: Actor,
48	  orgId: OrgId,
49	): Promise<BillingSummary> {
50	  assertOrgScope(actor, orgId);
51	  assertCan(actor, "org:manage_billing", billingResource(orgId));
52	
53	  const subscription = requireFound(
54	    await subscriptionRepo.findSubscription(orgId),
55	    "Subscription",
56	    orgId,
57	  );
58	
59	  const checks = await Promise.all(
60	    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
61	  );
62	
63	  const limits = getPlanLimits(subscription.plan);
64	
65	  return {
66	    orgId,
67	    subscription,
68	    checks,
69	    upcomingInvoiceCents:
70	      limits.priceCentsPerSeatMonthly *
71	      subscription.seats *
72	      (subscription.interval === "annual" ? 12 : 1),
73	  };
74	}
75	
76	/**
77	 * The one place a quota is evaluated. Every guard elsewhere calls this rather
78	 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
79	 * exactly two files: `plan-limits.ts` and `usageFor()` below.
80	 */
81	export async function checkLimit(
82	  orgId: OrgId,
83	  resource: LimitedResource,
84	  requested = 1,
85	): Promise<LimitCheck> {
86	  const plan = await planFor(orgId);
87	  const used = await usageFor(orgId, resource);
88	  const limit = getLimit(plan, resource);
89	
90	  return {
91	    resource,
92	    plan,
93	    limit,
94	    used,
95	    remaining: Math.max(0, limit - used),
96	    exceeded: wouldExceedLimit(plan, resource, used, requested),
97	  };
98	}
99	
100	/** Throwing form used by the create paths, and it emits the breach event. */
101	export async function assertWithinLimit(
102	  orgId: OrgId,
103	  resource: LimitedResource,
104	  requested = 1,
105	): Promise<void> {
106	  const check = await checkLimit(orgId, resource, requested);
107	  if (!check.exceeded) return;
108	
109	  await emit("billing.limit_exceeded", {
110	    orgId,
111	    actorId: null,
112	    occurredAt: toIsoTimestamp(new Date()),
113	    resource,
114	    limit: check.limit,
115	    used: check.used,
116	  });
117	
118	  throw new Error(
119	    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
120	  );
121	}
122	
123	/**
124	 * A downgrade is refused while the org is over the target plan's quota — the
125	 * alternative is silently breaking their workspace at the next write.
126	 */
127	export async function changePlan(
128	  actor: Actor,
129	  input: ChangePlanInput,
130	): Promise<Subscription> {
131	  assertOrgScope(actor, input.orgId);
132	  assertCan(actor, "org:manage_billing", billingResource(input.orgId));
133	
134	  const currentPlan = await planFor(input.orgId);
135	
136	  for (const resource of SUMMARY_RESOURCES) {
137	    const used = await usageFor(input.orgId, resource);
138	    if (wouldExceedLimit(input.plan, resource, used, 0)) {
139	      throw new Error(
140	        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
141	      );
142	    }
143	  }
144	
145	  const subscription = await subscriptionRepo.updateSubscriptionPlan(
146	    input.orgId,
147	    input.plan,
148	    input.interval,
149	  );
150	
151	  await emit("billing.plan_changed", {
152	    ...actorEnvelope(actor),
153	    from: currentPlan,
154	    to: input.plan,
155	  });
156	
157	  return subscription;
158	}
159	
160	export async function updateSeats(
161	  actor: Actor,
162	  input: UpdateSeatsInput,
163	): Promise<Subscription> {
164	  assertOrgScope(actor, input.orgId);
165	  assertCan(actor, "org:manage_billing", billingResource(input.orgId));
166	
167	  const plan = await planFor(input.orgId);
168	
169	  if (input.seats > getLimit(plan, "seats")) {
170	    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
171	  }
172	
173	  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
174	}
175	
176	/** Cancels at period end by default; `cancelImmediately` ends it now. */
177	export async function cancelSubscription(
178	  actor: Actor,
179	  input: CancelSubscriptionInput,
180	): Promise<Subscription> {
