/**
 * The storage the quota is charged: each file's size rounded up to whole
 * megabytes, summed. Integer division in SQL does the rounding, so a 0.3 MB
 * file costs 1 and a 1.5 MB file costs 2.
 */
export async function sumStorageMb(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({
      value: sql<
        number | null
      >`sum((${attachments.sizeBytes} + ${BYTES_PER_MB - 1}) / ${BYTES_PER_MB})`,
    })
    .from(attachments)
    .where(orgPredicate(attachments.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Megabytes one file is charged against the quota: its size rounded up. */
export function chargedMb(sizeBytes: number): number {
  return Math.ceil(sizeBytes / BYTES_PER_MB);
}

